/* ================= BASE STYLES & VARIABLES ================= */
html, body, #root, * {
  box-sizing: border-box;
  font-family: "Inter", system-ui, -apple-system, sans-serif !important;
}

html, body, #root {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden !important;
  background: transparent;
}

::-webkit-scrollbar {
  height: 8px;
  width: 8px;
}

::-webkit-scrollbar-track {
  background: var(--bg-hover);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb {
  background: var(--border-medium);
  border-radius: 4px;
}

:root {
  --primary: #2563eb;
  --primary-rgb: 37, 99, 235;
  --primary-hover: #1749b1;
  --text-dark: #1f2937;
  --text-muted: #6b7280;
  --border-light: #e5e7eb;
  --border-medium: #cbd5e1;
  --border-dark: #d1d5db;
  --bg-main: #ffffff;
  --bg-hover: #f9fafb;
  --bg-active: #f1f5f9;
  --bg-header: #f8fafc;
  --shadow-light: rgba(0, 0, 0, 0.04);
  --shadow-hover: rgba(0, 0, 0, 0.05);
}

.widget-container {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: var(--bg-main);
  border: 1px solid var(--border-light);
  border-radius: 12px;
  box-shadow: 0 2px 6px var(--shadow-light);
  overflow: hidden;
}

/* ================= HEADER & SEARCH ================= */
.dashboard-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 24px;
  border-bottom: 1px solid var(--border-light);
  flex-wrap: wrap;
  gap: 16px;
  flex-shrink: 0;
}

.header-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-dark);
  margin: 0;
}

.search-container {
  position: relative;
  width: 280px;
}

.search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
  pointer-events: none;
}

.search-input {
  width: 100%;
  padding: 10px 16px 10px 36px;
  font-size: 13px;
  border: 1px solid var(--border-dark);
  border-radius: 999px;
  outline: none;
  transition: all 0.2s;
  color: var(--text-dark);
}

.search-input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(var(--primary-rgb), 0.1);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.export-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 38px;
  padding: 0 18px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-dark);
  background-color: var(--bg-main);
  border: 1px solid var(--border-dark);
  border-radius: 999px;
  cursor: pointer;
  outline: none;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  user-select: none;
}

.export-btn:hover:not(:disabled) {
  background-color: var(--bg-hover);
  border-color: var(--border-medium);
  color: var(--primary);
  box-shadow: 0 1px 3px var(--shadow-hover);
}

.export-btn:active:not(:disabled) {
  background-color: var(--bg-active);
  transform: scale(0.98);
}

.export-btn:focus-visible {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(var(--primary-rgb), 0.15);
}

.export-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  background-color: #f3f4f6;
  border-color: var(--border-light);
  color: var(--text-muted);
}

.export-btn .download-icon {
  width: 15px;
  height: 15px;
  stroke-width: 2.2px;
  color: var(--text-muted);
  transition: color 0.2s ease;
}

.export-btn:hover:not(:disabled) .download-icon {
  color: var(--primary);
}

.export-btn:disabled .download-icon {
  color: var(--border-medium);
}

/* ================= TABLE STRUCTURE ================= */
.table-wrapper {
  flex-grow: 1;
  overflow: auto;
  background: var(--bg-main);
}

.pr-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  text-align: left;
  min-width: 1100px;
}

.pr-table th {
  position: sticky;
  top: 0;
  z-index: 10;
  background: var(--bg-header);
  padding: 14px 24px;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border-light);
  cursor: pointer;
  user-select: none;
  transition: background 0.2s;
  white-space: nowrap;
}

.pr-table th:hover {
  background: var(--bg-active);
  color: var(--text-dark);
}

.sort-icon {
  display: inline-block;
  margin-left: 6px;
  color: var(--text-muted);
}

.pr-table td {
  padding: 16px 24px;
  font-size: 13px;
  color: var(--text-dark);
  border-bottom: 1px solid #f3f4f6;
  height: 70px;
  vertical-align: middle;
}

.pr-table tr {
  transition: background-color 0.15s;
}

.pr-table tr:hover {
  background-color: var(--bg-hover);
  cursor: pointer;
}

.pr-table tr:last-child td {
  border-bottom: none;
}

/* ================= COLUMN SPECIFIC STYLES ================= */
.col-req {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.req-id-btn {
  font-weight: 700;
  color: var(--primary);
  font-size: 14px;
  cursor: pointer;
  text-decoration: underline dotted 1px;
  background: none;
  border: none;
  padding: 0;
  outline: none;
  transition: color 0.2s;
}

.req-id-btn:hover,
.req-id-btn:focus {
  color: var(--primary-hover);
  text-decoration: underline solid 2px;
}

.col-val {
  font-weight: 700;
  text-align: right;
  font-family: monospace;
  font-size: 14px;
}

/* PR State Chip */
.state-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 4px 12px;
  font-size: 11px;
  font-weight: 700;
  border-radius: 6px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.state-draft {
  background: #f3f4f6;
  color: #4b5563;
  border: 1px solid #e5e7eb;
}

.state-progress {
  background: #eff6ff;
  color: #2563eb;
  border: 1px solid #bfdbfe;
}

.state-pending {
  background: #fffbeb;
  color: #d97706;
  border: 1px solid #fde68a;
}

.state-approved {
  background: #ecfdf5;
  color: #059669;
  border: 1px solid #a7f3d0;
}

.state-rejected {
  background: #fef2f2;
  color: #dc2626;
  border: 1px solid #fecaca;
}

.state-completed {
  background: #f0fdfa;
  color: #0d9488;
  border: 1px solid #99f6e4;
}

.state-cancelled {
  background: #f8fafc;
  color: #64748b;
  border: 1px solid #cbd5e1;
}

.col-date {
  white-space: nowrap;
  color: var(--text-muted);
}

.col-entity {
  font-weight: 500;
}

/* ================= PAGINATION ================= */
.pagination-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 24px;
  border-top: 1px solid var(--border-light);
  background: var(--bg-main);
  flex-shrink: 0;
}

.page-info {
  font-size: 13px;
  color: var(--text-muted);
}

.page-controls {
  display: flex;
  align-items: center;
  gap: 16px;
}

.rows-selector {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--text-muted);
}

.rows-select {
  padding: 4px 8px;
  border: 1px solid #d1d5db;
  border-radius: 4px;
  font-size: 13px;
  outline: none;
  background: white;
  cursor: pointer;
}

.page-buttons {
  display: flex;
  gap: 4px;
}

.page-btn {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border-light);
  background: white;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-dark);
  cursor: pointer;
  transition: all 0.2s;
}

.page-btn:hover:not(:disabled) {
  background: #f1f5f9;
  border-color: #cbd5e1;
}

.page-btn.active {
  background: var(--primary);
  color: white;
  border-color: var(--primary);
}

.page-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ================= EMPTY & LOADING STATES ================= */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 40px;
  color: var(--text-muted);
}

.empty-icon {
  width: 64px;
  height: 64px;
  color: #cbd5e1;
  margin-bottom: 16px;
}

.empty-text {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-dark);
}

.skeleton-row {
  animation: pulse 1.5s infinite;
}

@keyframes pulse {
  0% {
    opacity: 0.6;
  }
  50% {
    opacity: 0.3;
  }
  100% {
    opacity: 0.6;
  }
}
.skeleton-box {
  height: 16px;
  background: #e2e8f0;
  border-radius: 4px;
  width: 100%;
}

.skeleton-box.w-half {
  width: 50%;
}

